#!/usr/bin/env python3
import sys, os, math, re, unicodedata
sys.setrecursionlimit(100000)

VERSION = "1.4.1"
HELP_TEXT = """  json-tui {OPTIONS} [file]

    A JSON terminal UI

  OPTIONS:

      file                              A JSON file. Omit to read from stdin.
      -h, --help                        Display this help menu.
