# ---------------- utilities ----------------

def dw(s):
    w = 0
    for ch in s:
        if ch == '\x00':
            continue
        o = ord(ch)
        if unicodedata.combining(ch):
            continue
        if o < 32 or (127 <= o < 160):
            continue
        if unicodedata.east_asian_width(ch) in ('W','F'):
            w += 2
        else:
            w += 1
    return w

def truncate_str(s, width):
    if width is None:
        return s
    if width <= 0:
        return ""
    out = []
    w = 0
    for ch in s:
        cw = dw(ch)
        if w + cw > width:
            break
        out.append(ch); w += cw
    return "".join(out)

def clean_controls(s, keep_newline=False):
    out = []
    for ch in s:
        if keep_newline and ch == '\n':
            out.append(ch)
        elif unicodedata.category(ch) == 'Cc':
            continue
        else:
            out.append(ch)
    return "".join(out)

# ================= JSON parser (nlohmann-like errors) =================

CONTROL_NAMES = {
    0:"NUL",1:"SOH",2:"STX",3:"ETX",4:"EOT",5:"ENQ",6:"ACK",7:"BEL",8:"BS",9:"HT",10:"LF",11:"VT",12:"FF",13:"CR",14:"SO",15:"SI",
    16:"DLE",17:"DC1",18:"DC2",19:"DC3",20:"DC4",21:"NAK",22:"SYN",23:"ETB",24:"CAN",25:"EM",26:"SUB",27:"ESC",28:"FS",29:"GS",30:"RS",31:"US"
}
CONTROL_ALT = {8:" or \\b",9:" or \\t",10:" or \\n",12:" or \\f",13:" or \\r"}

class JsonError(Exception):
    def __init__(self, message_bytes):
        super().__init__(message_bytes)
        self.message = message_bytes  # bytes without trailing newline

class Token:
    __slots__=('type','value','start','end')
    def __init__(self, t, v, s, e):
        self.type=t; self.value=v; self.start=s; self.end=e

# contexts: (label, expected_desc, expected_suffix_for_lexer_error or None)
CTX_VALUE = ("value", "'[', '{', or a literal", None)
CTX_EOF = ("value", "end of input", "end of input")
CTX_OBJ_KEY = ("object key", "string literal", "string literal")
CTX_OBJ_SEP = ("object separator", "':'", "':'")
CTX_OBJ = ("object", "'}'", "'}'")
CTX_ARRAY = ("array", "']'", "']'")

TOKEN_DESC = {
    'lbrace': "'{'", 'rbrace': "'}'", 'lbracket': "'['", 'rbracket': "']'",
    'comma': "','", 'colon': "':'", 'string': "string literal", 'number': "number literal",
    'true': "true literal", 'false': "false literal", 'null': "null literal", 'eof': "end of input",
}

class Parser:
    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.pos = 0
        self.diag_start = 0
        self.peeked = None
        self.peek_context = None
        # BOM
        if self.data.startswith(b'\xef\xbb\xbf'):
            self.pos = 3
        self.empty_candidate = (self.n == 0 or (self.n>0 and self.data[0:1]==b'\x00'))

    # ----- error helpers -----
    def transform_chunk(self, chunk_bytes):
        out = bytearray()
        for b in chunk_bytes:
            if b < 0x20:
                out.extend(("<U+%04X>" % b).encode())
            else:
                out.append(b)
        return bytes(out)

    def line_col(self, offset):
        data = self.data
        if offset < self.n and data[offset] == 10:
            line = 1 + data[:offset+1].count(b'\n')
            return line, 0
        if offset >= self.n:
            # EOF (or NUL-based EOF may pass offset < n but handled by caller? tokens use pos)
            segment = data[:offset] if offset <= self.n else data
            line = 1 + segment.count(b'\n')
            last = segment.rfind(b'\n')
            col = offset - last if last >= 0 else offset + 1
            # rfind returns index; if offset is byte index beyond, col = offset - last (if last=0? example newline at 0, offset1 ->1)
            # formula works: offset - last, when last==-1 use offset+1
            if last == -1:
                col = offset + 1
            else:
                col = offset - last
            return line, col
        else:
            segment = data[:offset]
            line = 1 + segment.count(b'\n')
            last = segment.rfind(b'\n')
            col = offset - last if last != -1 else offset + 1
            return line, col

    def make_error(self, offset, detail, context=None, is_lexer=True):
        line, col = self.line_col(offset)
        if is_lexer:
            # chunk
            if offset >= self.n:
                chunk = self.data[self.diag_start:self.n]
            else:
                chunk = self.data[self.diag_start:offset+1]
            chunk_t = self.transform_chunk(chunk)
            msg_detail = detail.encode() + b"; last read: '" + chunk_t + b"'"
            if context is not None and context[2] is not None:
                msg_detail += b"; expected " + context[2].encode()
            full = ("[json.exception.parse_error.101] parse error at line %d, column %d: syntax error while parsing %s - " % (line, col, context[0] if context else "value")).encode() + msg_detail
            return JsonError(full)
        else:
            full = ("[json.exception.parse_error.101] parse error at line %d, column %d: syntax error while parsing %s - %s" % (line, col, context[0], detail)).encode()
            return JsonError(full)

    def unexpected_error(self, token, context):
        # token position: for EOF, offset = token.start (which is pos), else token.end
        if token.type == 'eof':
            offset = token.start
            # line_col for EOF using offset as pos
            line, col = self.line_col_eof(offset)
            full = ("[json.exception.parse_error.101] parse error at line %d, column %d: syntax error while parsing %s - unexpected end of input; expected %s" % (line, col, context[0], context[1])).encode()
            return JsonError(full)
        offset = token.end
        line, col = self.line_col(offset)
        desc = TOKEN_DESC.get(token.type, token.type)
        full = ("[json.exception.parse_error.101] parse error at line %d, column %d: syntax error while parsing %s - unexpected %s; expected %s" % (line, col, context[0], desc, context[1])).encode()
        return JsonError(full)

    def line_col_eof(self, offset):
        segment = self.data[:offset]
        line = 1 + segment.count(b'\n')
        last = segment.rfind(b'\n')
        if last == -1:
            col = offset + 1
        else:
            col = offset - last
        return line, col

    # ----- lexer -----
    def skip_ws(self):
        d=self.data; n=self.n; p=self.pos
        while p < n and d[p] in (32,9,10,13):
            p+=1
        self.pos=p

    def scan_token(self, context):
        if self.peeked is not None:
            tok = self.peeked; self.peeked=None; return tok
        return self._scan_token(context)

    def peek_token(self, context):
        if self.peeked is None:
            self.peeked = self._scan_token(context)
            self.peek_context = context
        return self.peeked

    def _scan_token(self, context):
        self.skip_ws()
        d=self.data; n=self.n; p=self.pos
        if p>=n or (p<n and d[p]==0):
            # EOF token start = p (for NUL, p is index of NUL)
            return Token('eof', None, p, p)
        c=d[p]
        if c==123: # {
            self.pos=p+1; return Token('lbrace', None, p, p)
        if c==125:
            self.pos=p+1; return Token('rbrace', None, p, p)
        if c==91:
            self.pos=p+1; return Token('lbracket', None, p, p)
        if c==93:
            self.pos=p+1; return Token('rbracket', None, p, p)
        if c==44:
            self.pos=p+1; return Token('comma', None, p, p)
        if c==58:
            self.pos=p+1; return Token('colon', None, p, p)
        if c==34: # "
            self.diag_start=p
            return self.scan_string(context)
        if c==45 or (48 <= c <= 57):
            self.diag_start=p
            return self.scan_number(context)
        if c==116: # t
            return self.scan_literal(b"true", 'true', True, context)
        if c==102:
            return self.scan_literal(b"false", 'false', False, context)
        if c==110:
            return self.scan_literal(b"null", 'null', None, context)
        # invalid literal - single char
        raise self.make_error(p, "invalid literal", context, True)

    def scan_literal(self, word, ttype, val, context):
        start=self.pos
        for i, exp in enumerate(word):
            p=start+i
            if p>=self.n:
                raise self.make_error(self.n, "invalid literal", context, True)
            if self.data[p]==0:
                # treated as EOF mismatch
                raise self.make_error(p, "invalid literal", context, True)
            if self.data[p]!=exp:
                raise self.make_error(p, "invalid literal", context, True)
        self.pos=start+len(word)
        return Token(ttype, val, start, self.pos-1)

    def scan_number(self, context):
        d=self.data; n=self.n; start=self.pos; i=start
        if d[i]==45: # '-'
            i+=1
            if i>=n or not (48 <= d[i] <= 57):
                # error offset i (may be n)
                offset = i if i<=n else n
                raise self.make_error(offset if offset<=n else n, "invalid number; expected digit after '-'", context, True) if False else self._number_error(i, "invalid number; expected digit after '-'", context)
        # int part
        if i < n and d[i]==48:
            i+=1
        elif i < n and 49 <= d[i] <= 57:
            while i<n and 48 <= d[i] <= 57:
                i+=1
        else:
            # should not happen (caller ensures digit/minus)
            raise self._number_error(i, "invalid number", context)
        is_float=False
        if i<n and d[i]==46: # .
            is_float=True
            i+=1
            if i>=n or not (48 <= d[i] <= 57):
                raise self._number_error(i, "invalid number; expected digit after '.'", context)
            while i<n and 48 <= d[i] <= 57:
                i+=1
        if i<n and d[i] in (101,69): # e E
            is_float=True
            i+=1
            if i<n and d[i] in (43,45):
                i+=1
                if i>=n or not (48 <= d[i] <= 57):
                    raise self._number_error(i, "invalid number; expected digit after exponent sign", context)
            else:
                if i>=n or not (48 <= d[i] <= 57):
                    raise self._number_error(i, "invalid number; expected '+', '-', or digit after exponent", context)
            while i<n and 48 <= d[i] <= 57:
                i+=1
        text = d[start:i].decode('ascii')
        self.pos=i
        tok_end=i-1
        # conversion
        if is_float:
            try:
                v=float(text)
            except Exception:
                v=math.inf
            if math.isinf(v):
                # check mantissa zero?
                # float('0e999') is 0.0 in python, so inf only when mantissa nonzero
                raise JsonError(("[json.exception.out_of_range.406] number overflow parsing '%s'" % text).encode())
            return Token('number', ('float', v), start, tok_end)
        else:
            # integer
            try:
                iv=int(text)
            except Exception:
                iv=0
            if text.startswith('-'):
                if iv >= -(1<<63):
                    return Token('number', ('int', iv), start, tok_end)
                else:
                    fv=float(text)
                    if math.isinf(fv):
                        raise JsonError(("[json.exception.out_of_range.406] number overflow parsing '%s'" % text).encode())
                    return Token('number', ('float', fv), start, tok_end)
            else:
                if iv <= (1<<64)-1:
                    return Token('number', ('int', iv), start, tok_end)
                else:
                    fv=float(text)
                    if math.isinf(fv):
                        raise JsonError(("[json.exception.out_of_range.406] number overflow parsing '%s'" % text).encode())
                    return Token('number', ('float', fv), start, tok_end)

    def _number_error(self, offset, detail, context):
        # offset may be >=n (EOF)
        if offset>self.n: offset=self.n
        return self.make_error(offset, detail, context, True)

    def scan_string(self, context):
        d=self.data; n=self.n; start=self.pos; i=start+1
        out_chars=[]
        while True:
            if i>=n:
                raise self.make_error(n, "invalid string: missing closing quote", context, True)
            b=d[i]
            if b==34: # closing
                self.pos=i+1
                return Token('string', "".join(out_chars), start, i)
            if b==92: # backslash
                if i+1>=n:
                    raise self.make_error(n, "invalid string: missing closing quote", context, True)
                esc=d[i+1]
                if esc==34: out_chars.append('"'); i+=2; continue
                if esc==92: out_chars.append('\\'); i+=2; continue
                if esc==47: out_chars.append('/'); i+=2; continue
                if esc==98: out_chars.append('\b'); i+=2; continue
                if esc==102: out_chars.append('\f'); i+=2; continue
                if esc==110: out_chars.append('\n'); i+=2; continue
                if esc==114: out_chars.append('\r'); i+=2; continue
                if esc==116: out_chars.append('\t'); i+=2; continue
                if esc==117: # u
                    code, ni = self.scan_u(i, context)
                    # surrogate handling
                    if 0xD800 <= code <= 0xDBFF:
                        # need following \u
                        # ni points after first escape
                        if ni>=n:
                            raise self.make_error(n, "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF", context, True)
                        if d[ni]!=92: # not backslash
                            raise self.make_error(ni, "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF", context, True)
                        if ni+1>=n:
                            raise self.make_error(n, "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF", context, True)
                        if d[ni+1]!=117: # 'u'
                            raise self.make_error(ni+1, "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF", context, True)
                        code2, ni2 = self.scan_u(ni, context)
                        if not (0xDC00 <= code2 <= 0xDFFF):
                            # error at last hex digit of second escape (ni+5)
                            raise self.make_error(ni+5, "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF", context, True)
                        combined = 0x10000 + (((code-0xD800)<<10) | (code2-0xDC00))
                        out_chars.append(chr(combined)); i=ni2; continue
                    elif 0xDC00 <= code <= 0xDFFF:
                        raise self.make_error(i+5, "invalid string: surrogate U+DC00..U+DFFF must follow U+D800..U+DBFF", context, True)
                    else:
                        out_chars.append(chr(code)); i=ni; continue
                else:
                    raise self.make_error(i+1, "invalid string: forbidden character after backslash", context, True)
            if b < 0x20:
                name = CONTROL_NAMES.get(b, "")
                alt = CONTROL_ALT.get(b, "")
                detail = "invalid string: control character U+%04X (%s) must be escaped to \\u%04X%s" % (b, name, b, alt)
                raise self.make_error(i, detail, context, True)
            if b >= 0x80:
                ch, ni, err_off = self.decode_utf8(i)
                if err_off is not None:
                    raise self.make_error(err_off, "invalid string: ill-formed UTF-8 byte", context, True)
                out_chars.append(ch); i=ni; continue
            else:
                out_chars.append(chr(b)); i+=1; continue

    def scan_u(self, slash_index, context):
        # slash_index at '\', following is 'u' at +1, hex at +2..+5
        d=self.data; n=self.n
        code=0
        for j in range(4):
            p=slash_index+2+j
            if p>=n:
                raise self.make_error(n, "invalid string: '\\u' must be followed by 4 hex digits", context, True)
            c=d[p]
            if (48 <= c <= 57) or (65 <= c <= 70) or (97 <= c <= 102):
                code = code*16 + int(chr(c), 16)
            else:
                raise self.make_error(p, "invalid string: '\\u' must be followed by 4 hex digits", context, True)
        return code, slash_index+6

    def decode_utf8(self, i):
        d=self.data; n=self.n; b=d[i]
        if 0xC2 <= b <= 0xDF:
            if i+1>=n:
                return None, None, n
            b2=d[i+1]
            if not (0x80 <= b2 <= 0xBF):
                return None, None, i+1
            return chr(((b & 0x1F)<<6) | (b2 & 0x3F)), i+2, None
        if b==0xE0:
            if i+1>=n: return None,None,n
            b2=d[i+1]
            if not (0xA0 <= b2 <= 0xBF): return None,None,i+1
            if i+2>=n: return None,None,n
            b3=d[i+2]
            if not (0x80 <= b3 <= 0xBF): return None,None,i+2
            return chr(((b & 0x0F)<<12)|((b2&0x3F)<<6)|(b3&0x3F)), i+3, None
        if 0xE1 <= b <= 0xEC or 0xEE <= b <= 0xEF:
            if i+1>=n: return None,None,n
            b2=d[i+1]
            if not (0x80 <= b2 <= 0xBF): return None,None,i+1
            if i+2>=n: return None,None,n
            b3=d[i+2]
            if not (0x80 <= b3 <= 0xBF): return None,None,i+2
            return chr(((b & 0x0F)<<12)|((b2&0x3F)<<6)|(b3&0x3F)), i+3, None
        if b==0xED:
            if i+1>=n: return None,None,n
            b2=d[i+1]
            if not (0x80 <= b2 <= 0x9F): return None,None,i+1
            if i+2>=n: return None,None,n
            b3=d[i+2]
            if not (0x80 <= b3 <= 0xBF): return None,None,i+2
            return chr(((b & 0x0F)<<12)|((b2&0x3F)<<6)|(b3&0x3F)), i+3, None
        if b==0xF0:
            if i+1>=n: return None,None,n
            b2=d[i+1]
            if not (0x90 <= b2 <= 0xBF): return None,None,i+1
            if i+2>=n: return None,None,n
            b3=d[i+2]
            if not (0x80 <= b3 <= 0xBF): return None,None,i+2
            if i+3>=n: return None,None,n
            b4=d[i+3]
            if not (0x80 <= b4 <= 0xBF): return None,None,i+3
            return chr(((b & 0x07)<<18)|((b2&0x3F)<<12)|((b3&0x3F)<<6)|(b4&0x3F)), i+4, None
        if 0xF1 <= b <= 0xF3:
            if i+1>=n: return None,None,n
            b2=d[i+1]
            if not (0x80 <= b2 <= 0xBF): return None,None,i+1
            if i+2>=n: return None,None,n
            b3=d[i+2]
            if not (0x80 <= b3 <= 0xBF): return None,None,i+2
            if i+3>=n: return None,None,n
            b4=d[i+3]
            if not (0x80 <= b4 <= 0xBF): return None,None,i+3
            return chr(((b & 0x07)<<18)|((b2&0x3F)<<12)|((b3&0x3F)<<6)|(b4&0x3F)), i+4, None
        if b==0xF4:
            if i+1>=n: return None,None,n
            b2=d[i+1]
            if not (0x80 <= b2 <= 0x8F): return None,None,i+1
            if i+2>=n: return None,None,n
            b3=d[i+2]
            if not (0x80 <= b3 <= 0xBF): return None,None,i+2
            if i+3>=n: return None,None,n
            b4=d[i+3]
            if not (0x80 <= b4 <= 0xBF): return None,None,i+3
            return chr(((b & 0x07)<<18)|((b2&0x3F)<<12)|((b3&0x3F)<<6)|(b4&0x3F)), i+4, None
        # invalid lead
        return None, None, i

    # ----- parser -----
    def parse(self):
        # empty check
        # Peek first token; if EOF and no data consumed meaningful
        # Determine emptiness: if data (excluding BOM) stripped is empty and first char not whitespace?
        # We approximate: if self.n==0 or data starts with \x00 => empty
        # Also if after BOM, there is nothing, original says unexpected EOF (BOM consumed) so not empty
        if self.n==0 or (self.n>=1 and self.data[0]==0):
            raise JsonError(b"[json.exception.parse_error.101] parse error at line 1, column 1: attempting to parse an empty input; check that your input string or stream contains the expected JSON")
        val = self.parse_value()
        tok = self.scan_token(CTX_EOF)
        if tok.type != 'eof':
            raise self.unexpected_error(tok, CTX_EOF)
        return val

    def parse_value(self, first_tok=None):
        tok = first_tok if first_tok is not None else self.scan_token(CTX_VALUE)
        return self.parse_value_from(tok)

    def parse_value_from(self, tok):
        if tok.type=='lbrace':
            return self.parse_object()
        if tok.type=='lbracket':
            return self.parse_array()
        if tok.type=='string':
            return ('string', tok.value)
        if tok.type=='number':
            return tok.value  # ('int',v) or ('float',v)
        if tok.type=='true':
            return ('bool', True)
        if tok.type=='false':
            return ('bool', False)
        if tok.type=='null':
            return ('null', None)
        raise self.unexpected_error(tok, CTX_VALUE)

    def parse_object(self):
        obj={}
        tok=self.scan_token(CTX_OBJ_KEY)
        if tok.type=='rbrace':
            return ('object', obj)
        while True:
            if tok.type!='string':
                raise self.unexpected_error(tok, CTX_OBJ_KEY)
            key=tok.value
            tok2=self.scan_token(CTX_OBJ_SEP)
            if tok2.type!='colon':
                raise self.unexpected_error(tok2, CTX_OBJ_SEP)
            val=self.parse_value()
            obj[key]=val
            tok=self.scan_token(CTX_OBJ)
            if tok.type=='rbrace':
                break
            if tok.type=='comma':
                tok=self.scan_token(CTX_OBJ_KEY)
                continue
            raise self.unexpected_error(tok, CTX_OBJ)

        return ('object', obj)

    def parse_array(self):
        arr=[]
        tok=self.scan_token(CTX_VALUE)
        if tok.type=='rbracket':
            return ('array', arr)
        while True:
            val=self.parse_value_from(tok)
            arr.append(val)
            tok=self.scan_token(CTX_ARRAY)
            if tok.type=='rbracket':
                break
            if tok.type=='comma':
                tok=self.scan_token(CTX_VALUE)
                continue
            raise self.unexpected_error(tok, CTX_ARRAY)
        return ('array', arr)

def format_float(v):
    if math.isnan(v):
        return "nan"
    if math.isinf(v):
        return "inf" if v>0 else "-inf"
    if v==0.0:
        return "-0.0" if math.copysign(1.0, v) < 0 else "0.0"
    s=repr(v)
    if 'e' in s or 'E' in s:
        # python already scientific like 1e+16, 9.9e-05 etc - keep, ensure exponent formatting
        mant, exp = s.lower().split('e')
        e=int(exp)
        # mantissa may be like '1' - keep as is, but repr gives '1e+16'
        return "%se%+02d" % (mant, e) if abs(e) < 100 else "%se%+d" % (mant, e)
    # fixed
    # decide scientific if exponent >=15
    # get sign
    sign=""
    t=s
    if t.startswith('-'):
        sign="-"; t=t[1:]
    if '.' in t:
        intpart, fracpart = t.split('.',1)
    else:
        intpart, fracpart = t, ""
    int_stripped = intpart.lstrip('0')
    if int_stripped:
        exp10 = len(int_stripped)-1
        if exp10 >= 15:
            digits = (int_stripped + fracpart).rstrip('0')
            # digits corresponds to mantissa digits
            if len(digits)==1:
                mant = digits
            else:
                mant = digits[0] + '.' + digits[1:]
            return "%s%se%+02d" % (sign, mant, exp10)
    return s

# ================= Node model =================

class Node:
    __slots__=('kind','raw','key','parent','children','opened','build_depth','view_mode','table_cells','table_columns','row_active_col','cell_of','header_button','token_focus','button_focus','last_focus_inside')
    def __init__(self, kind, raw, key, parent, build_depth):
        self.kind=kind
        self.raw=raw
        self.key=key
        self.parent=parent
        self.children=[]
        self.opened=False
        self.build_depth=build_depth
        self.view_mode='tree'
        self.table_cells=None
        self.table_columns=None
        self.row_active_col=None
        self.cell_of=None  # tuple (table_node,row,col)
        self.header_button='token'  # 'token' or 'button'
        self.token_focus=None
        self.button_focus=None
        self.last_focus_inside=None  # for cell nodes: last focus node inside

    def is_container(self):
        return self.kind in ('object','array')

def initial_open(kind, depth):
    if kind=='object':
        return depth<=1
