# ================= Rendering / App =================

class Seg:
    __slots__=('t','fg','bold','rev','hit')
    def __init__(self, t, fg=None, bold=False, rev=False, hit=None):
        self.t=t; self.fg=fg; self.bold=bold; self.rev=rev; self.hit=hit

class Focus:
    __slots__=('node','kind')
    def __init__(self, node, kind):
        self.node=node; self.kind=kind  # 'node' or 'button'
    def __repr__(self):
        return f"<Focus {self.kind} {self.node.kind if self.node else None}>"

def get_token_focus(node):
    if node.token_focus is None:
        node.token_focus=Focus(node,'node')
    return node.token_focus
def get_button_focus(node):
    if node.button_focus is None:
        node.button_focus=Focus(node,'button')
    return node.button_focus

def wrap_paragraph(text, width):
    # text already control-cleaned except newline
    if width is None or width<=0:
        # unlimited
        lines=[]
        for part in text.split('\n'):
            if part=='':
                continue
            lines.append(part)
        return lines
    result=[]
    parts=text.split('\n')
    for part in parts:
        if part=='':
            continue
        # tokenise: each space is a token, words are runs of non-space
        tokens=[]
        i=0
        while i < len(part):
            if part[i]==' ':
                tokens.append(' '); i+=1
            else:
                j=i
                while j < len(part) and part[j]!=' ':
                    j+=1
                tokens.append(part[i:j]); i=j
        cur=""; cur_w=0
        # Track whether we are at start of a segment (preserve leading spaces)
        at_segment_start=True
        skip_leading_space=False
        for tok in tokens:
            is_space=(tok==' ')
            tw=dw(tok)
            if not is_space and tw>width:
                # overlong word
                if cur:
                    result.append(cur); cur=""; cur_w=0
                result.append(truncate_str(tok, width))
                # next separator space should be skipped
                skip_leading_space=True
                at_segment_start=False
                continue
            if is_space:
                if skip_leading_space and cur=="":
                    # separator after a truncated word or after a line break: drop it
                    continue
                if cur=="" and not at_segment_start:
                    continue
                if cur_w+1 <= width:
                    cur+=tok; cur_w+=1
                else:
                    # space doesn't fit: finish line, drop space
                    if cur:
                        result.append(cur)
                    cur=""; cur_w=0
                    skip_leading_space=True
                continue
            # word
            skip_leading_space=False
            if cur_w+tw <= width:
                cur+=tok; cur_w+=tw
            else:
                if cur:
                    result.append(cur)
                cur=tok; cur_w=tw
            at_segment_start=False
        if cur or (part and False):
            result.append(cur)
    return result

def truncate_segments(segs, width):
    if width is None:
        return list(segs)
    out=[]; remaining=width
    for s in segs:
        if remaining<=0: break
        w=dw(s.t)
        if w<=remaining:
            out.append(Seg(s.t, s.fg, s.bold, s.rev, s.hit)); remaining-=w
        else:
            nt=truncate_str(s.t, remaining)
            if nt:
                out.append(Seg(nt, s.fg, s.bold, s.rev, s.hit))
            remaining=0; break
    return out

class App:
    def __init__(self, root, fullscreen, out_fd, input_fd):
        self.root=root
        self.fullscreen=fullscreen
        self.out_fd=out_fd
        self.input_fd=input_fd
        self.focus=get_token_focus(root)
        self.pending_g=False
        self.exit_requested=False
        self.scroll_offset=0
        self.last_lines=[]
        self.focus_line=None
        self.hit_map={}  # line_index -> [(x0,x1,Focus)]
        self.term_w, self.term_h = self.get_term_size()
        self.inline_top_row=None  # 0-based screen row for inline mode, if known
        self.table_build_for=set()

    def get_term_size(self):
        for fd in (self.out_fd, self.input_fd, 2, 1, 0):
            try:
                sz=os.get_terminal_size(fd)
                if sz.columns>0 and sz.lines>0:
                    return sz.columns, sz.lines
            except Exception:
                continue
        # env fallback
        try:
            import shutil
            sz=shutil.get_terminal_size(fallback=(80,24))
            return sz.columns, sz.lines
        except Exception:
            return 80,24

    # ---------- table building ----------
    def build_table(self, node):
        columns=[]
        rows_cells=[]
        # node.children are row objects (in tree mode)
        for row_node in node.children:
            d={}
            if row_node.kind=='object':
                for child in row_node.children:
                    col=child.key
                    if col not in columns:
                        columns.append(col)
                    # build cell node
                    cell=build_node(child.raw, 1, None, None)
                    cell.cell_of=(node, len(rows_cells), col)
                    cell.last_focus_inside=get_token_focus(cell)
                    d[col]=cell
            rows_cells.append(d)
        node.table_columns=columns
        node.table_cells=rows_cells
        node.row_active_col=[]
        for d in rows_cells:
            chosen=None
            for col in columns:
                if col in d:
                    chosen=col; break
            node.row_active_col.append(chosen)

    def enter_table(self, node):
        if not is_table_eligible(node):
            return
        node.view_mode='table'
        node.header_button='button'
        self.build_table(node)
        self.focus=get_button_focus(node)

    def exit_table(self, node):
        node.view_mode='tree'
        node.table_cells=None
        node.table_columns=None
        node.row_active_col=None
        rebuild_array_children(node)
        node.header_button='button'
        self.focus=get_button_focus(node)

    # ---------- focus helpers ----------
    def resolve_node(self, node):
        # returns focus representing landing on this node (using its header memory)
        if node.view_mode=='table':
            return get_button_focus(node)
        if node.header_button=='button' and is_table_eligible(node):
            return get_button_focus(node)
        return get_token_focus(node)

    def set_focus(self, foc):
        if foc is None:
            return
        self.focus=foc
        node=foc.node
        if foc.kind=='button':
            node.header_button='button'
        else:
            # token focus, but if node is in table mode, its token does not exist; ignore
            if node.view_mode!='table':
                node.header_button='token'
        # update cell memories and row active
        # walk enclosing cell roots
        cur_node=node
        seen=set()
        while cur_node is not None and id(cur_node) not in seen:
            seen.add(id(cur_node))
            frag_root=self.fragment_root(cur_node)
            if frag_root is not None and frag_root.cell_of is not None:
                # this cur_node is inside frag_root cell
                frag_root.last_focus_inside=foc
                table_node, row_idx, col = frag_root.cell_of
                if table_node.row_active_col is not None and 0 <= row_idx < len(table_node.row_active_col):
                    table_node.row_active_col[row_idx]=col
                cur_node=table_node
                continue
            break

    def fragment_root(self, node):
        cur=node
        while cur is not None and cur.parent is not None:
            cur=cur.parent
        return cur

    def enclosing_table(self, node):
        """returns (table_node, cell_root) if node is inside a table cell, else None"""
        frag=self.fragment_root(node)
        if frag is not None and frag.cell_of is not None:
            return (frag.cell_of[0], frag)
        return None

    # ---------- visible traversals ----------
    def visible_nodes_fragment(self, frag_root):
        out=[]
        def rec(n):
            out.append(n)
            if n.view_mode=='table':
                return
            if n.is_container() and n.opened:
                for ch in n.children:
                    rec(ch)
        rec(frag_root)
        return out

    def full_nodes_fragment(self, frag_root):
        out=[]
        def rec(n):
            out.append(n)
            if n.view_mode=='table':
                return
            if n.is_container():
                for ch in n.children:
                    rec(ch)
        rec(frag_root)
