    def visible_children(self, node):
        if node.view_mode=='table':
            return []
        if node.is_container() and node.opened:
            return list(node.children)
        return []

    # ---------- rendering ----------
    def render_node_block(self, node, indent_level, width_limit):
        # returns list of lines (list of Seg)
        if node.view_mode=='table' and node.kind=='array':
            lines=[]
            segs=[]
            indent_txt='  '*indent_level
