    # ---------- navigation: tree ----------
    def tree_move(self, node, direction, from_button=False):
        frag=self.fragment_root(node)
        vis=self.visible_nodes_fragment(frag)
        # if node in vis
        if node in vis:
            idx=vis.index(node)
            nid=idx+direction
            if 0 <= nid < len(vis):
                return vis[nid]
            return None
        else:
            full=self.full_nodes_fragment(frag)
            if node not in full:
                return None
            idx=full.index(node)
            vis_set=set(id(x) for x in vis)
            if direction>0:
                for cand in full[idx+1:]:
                    if id(cand) in vis_set:
                        return cand
            else:
                for cand in reversed(full[:idx]):
                    if id(cand) in vis_set:
                        return cand
            return None

    def last_visible_descendant(self, node):
        # node is in its fragment; return last visible node in subtree rooted at node (including nested table? caller handles tables)
        frag=self.fragment_root(node)
