        # nodes in vis that are in subtree of node: walk
        # Build set of subtree nodes from full traversal starting at node
        subtree=[]
        def rec(n):
            subtree.append(n)
            if n.view_mode=='table': return
            if n.is_container():
                for ch in n.children: rec(ch)
        rec(node)
        subtree_set=set(id(x) for x in subtree)
        candidates=[x for x in vis if id(x) in subtree_set]
        return candidates[-1] if candidates else node

