    def handle_event(self, ev):
        # ev tuples
        kind=ev[0]
        if kind=='resize':
            return
        # mouse wheel before pending reset? Mouse events reset pending as non-g
        if kind!='char_g':
            self.pending_g=False
        if kind=='quit':
            self.exit_requested=True; return
        if kind=='char':
            ch=ev[1]
            if ch=='q':
                self.exit_requested=True; return
            if ch=='g':
                if self.pending_g:
                    self.pending_g=False; self.go_bottom()
                else:
                    self.pending_g=True
                return
            if ch=='G':
                self.go_top(); return
            if ch=='j':
                self.move_down(); return
            if ch=='k':
                self.move_up(); return
            if ch=='h':
                self.move_left(); return
            if ch=='l':
                self.move_right(); return
            if ch=='+':
                self.do_expand(); return
            if ch=='-':
                self.do_collapse(); return
            # other chars ignored
            return
        if kind=='key':
            name=ev[1]
            if name=='down': self.move_down()
            elif name=='up': self.move_up()
            elif name=='right': self.move_right()
            elif name=='left': self.move_left()
            elif name=='enter' or name=='space': self.do_toggle()
            elif name=='pageup': self.page_up()
            elif name=='pagedown': self.page_down()
            elif name=='tab':
                # move to next visible; wrap to first after root if needed
                before=self.focus
                self.move_down()
                if self.focus==before:
                    vis=self.visible_nodes_fragment(self.root)
                    if len(vis)>1:
                        self.set_focus(self.resolve_node(vis[1]))
            elif name=='shift_tab':
                before=self.focus
                self.move_up()
                if self.focus==before:
                    vis=self.visible_nodes_fragment(self.root)
                    if vis:
                        self.set_focus(self.resolve_node(vis[-1]))
            # home/end/others no-op
            return
        if kind=='mouse':
            _, btn, x, y, is_release = ev
            if btn==64:
                self.move_up(); return
            if btn==65:
                self.move_down(); return
            if btn in (66,67):
                return
            # position to focus
            target=self.mouse_hit(x,y)
            if target is not None:
                if not is_release and btn==0:
                    self.set_focus(target)
                    # activate
                    if target.kind=='button':
                        self.do_toggle()
                    elif target.node.is_container():
                        # mouse toggle for node tokens (in tables cells etc too)
                        target.node.opened=not target.node.opened
                    # scalar: nothing
                else:
                    # moves/release/etc: only focus
                    self.set_focus(target)
            return

    def mouse_hit(self, x, y):
        # overridden by controller? App knows last viewport stored on controller via attributes set during draw
        # Controller will inject attributes: screen_offset, inline_top, last_vh, term dims
