class InputParser:
    def __init__(self):
        self.buf=bytearray()
    def feed(self, data):
        self.buf.extend(data)
        events=[]
        while self.buf:
            ev, consumed = self.try_parse_one()
            if ev is None and consumed==0:
                break
            if consumed>0:
                del self.buf[:consumed]
            if ev is not None:
                events.append(ev)
            if consumed==0:
                break
        return events
    def try_parse_one(self):
        buf=self.buf
        if not buf:
            return None,0
        b=buf[0]
        if b==27: # ESC
            if len(buf)==1:
                # lone escape - treat as escape
                return ('quit',),1
            if buf[1]==91: # [
                if len(buf)>=3 and buf[2]==60: # '<' mouse
                    # find M/m
                    for i in range(3, len(buf)):
                        if buf[i] in (77,109): # M,m
                            seq=bytes(buf[3:i]).decode('ascii', 'ignore')
                            is_release=(buf[i]==109)
                            parts=seq.split(';')
                            try:
                                btn=int(parts[0]); x=int(parts[1]); y=int(parts[2])
