import termios, tty, signal, select

class Controller:
    def __init__(self, app, out_fd, input_fd, fullscreen):
        self.app=app
        self.out_fd=out_fd
        self.input_fd=input_fd
        self.fullscreen=fullscreen
        self.old_term=None
        self.printed_height=0
        self.first=True
        self.wake_r=None; self.wake_w=None
        self.resize_pending=False
        self.inline_top=None
        self.parser=InputParser()
        self._sigwinch_old=None
        self._sigcont_old=None

    def get_size(self):
        return self.app.get_term_size()

    def term_setup(self):
        if self.input_fd is not None and self.input_fd>=0:
            try:
                if os.isatty(self.input_fd):
                    self.old_term=termios.tcgetattr(self.input_fd)
                    tty.setraw(self.input_fd)
            except Exception:
                self.old_term=None
        seq=b""
        if self.fullscreen:
            seq+=b"\x1b[?1049h"
        seq+=b"\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?25l"
        try: os.write(self.out_fd, seq)
        except Exception: pass

    def term_restore(self):
        seq=b""
        # inline: move below frame
        if not self.fullscreen and self.printed_height>0:
            seq+=b"\r\n"
        seq+=b"\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?25h"
        if self.fullscreen:
            seq+=b"\x1b[?1049l"
        try: os.write(self.out_fd, seq)
        except Exception: pass
        if self.old_term is not None:
            try: termios.tcsetattr(self.input_fd, termios.TCSADRAIN, self.old_term)
            except Exception: pass
            self.old_term=None

    def query_inline_top(self):
        if self.fullscreen: return
        try:
            if not os.isatty(self.out_fd) or not os.isatty(self.input_fd):
                return
        except Exception:
            return
        try:
            os.write(self.out_fd, b"\x1b[6n")
            # wait briefly
            r,_,_=select.select([self.input_fd],[],[],0.25)
            if not r: return
            data=os.read(self.input_fd, 1024)
            # parse ESC [ row ; col R
            # could contain other
            import re
            m=re.search(br'\x1b\[(\d+);(\d+)R', data)
            if m:
                self.inline_top=int(m.group(1))-1
                self.app._inline_top=self.inline_top
            # if there were extra bytes, feed them to parser later? store
            if data and not m:
                # feed later - put into a stash
                self.parser.buf.extend(data)
            elif data:
                # bytes before/after match ignored
                pass
        except Exception:
            return

    def line_to_bytes(self, segs, term_w):
        out=bytearray()
        width=0
        for s in segs:
            if not s.t:
                continue
            if s.bold or s.rev or s.fg is not None:
                out.extend(b"\x1b[0m")
                if s.bold: out.extend(b"\x1b[1m")
                if s.rev: out.extend(b"\x1b[7m")
                if s.fg is not None: out.extend(("\x1b[%dm"%s.fg).encode())
                out.extend(s.t.encode('utf-8', 'surrogatepass'))
                out.extend(b"\x1b[0m")
            else:
                out.extend(s.t.encode('utf-8', 'surrogatepass'))
            width+=dw(s.t)
        return bytes(out), width

    def draw(self):
        app=self.app
        w,h=self.get_size()
        app.term_w, app.term_h = w,h
        lines=app.generate_lines(w)
        total=len(lines)
        if self.fullscreen:
            vh=h
        else:
            vh=min(h, total) if total>0 else h
            if vh<=0: vh=h
        # offset
        if app.focus_line is not None:
            desired=app.focus_line - (vh//2)
            maxoff=max(0, total-vh)
            if desired<0: desired=0
            if desired>maxoff: desired=maxoff
            app.scroll_offset=desired
        else:
            maxoff=max(0, total-vh)
            if app.scroll_offset>maxoff: app.scroll_offset=maxoff
        offset=app.scroll_offset
        viewport=lines[offset:offset+vh]
        # pad viewport to vh for fullscreen
        app._vp_offset=offset; app._vp_w=w; app._inline_top=self.inline_top
        app._vp_h=vh
        if self.fullscreen:
            out=bytearray()
            out.extend(b"\x1b[H")
            for i in range(vh):
                out.extend(("\x1b[%d;1H\x1b[2K"% (i+1)).encode())
                if i < len(viewport):
                    bts, width = self.line_to_bytes(viewport[i], w)
                    out.extend(bts)
                    if width < w:
                        out.extend(b' '*(w-width))
                # else blank cleared
            try: os.write(self.out_fd, bytes(out))
            except Exception: pass
            self.printed_height=vh
            self.first=False
        else:
            out=bytearray()
            if not self.first and self.printed_height>0:
                if self.printed_height>1:
                    out.extend(("\x1b[%dA"% (self.printed_height-1)).encode())
                out.extend(b"\r")
            for i, line in enumerate(viewport):
                out.extend(b"\x1b[2K\r")
                bts, width = self.line_to_bytes(line, w)
                out.extend(bts)
                if i != len(viewport)-1:
                    out.extend(b"\r\n")
            new_h=len(viewport)
            if not self.first and new_h < self.printed_height:
                extra=self.printed_height-new_h
                for _ in range(extra):
                    out.extend(b"\r\n\x1b[2K")
                if extra>0:
                    out.extend(("\x1b[%dA\r"%extra).encode())
            try: os.write(self.out_fd, bytes(out))
            except Exception: pass
            self.printed_height=new_h
            self.first=False

    def suspend(self):
        self.term_restore()
        # reset printed state after resume we will redraw fresh inline
        old_handler=signal.getsignal(signal.SIGTSTP)
        try:
            signal.signal(signal.SIGTSTP, signal.SIG_DFL)
            os.kill(os.getpid(), signal.SIGTSTP)
        finally:
            # after resume
            try: signal.signal(signal.SIGTSTP, old_handler)
            except Exception: pass
        self.term_setup()
        self.first=True; self.printed_height=0
        if not self.fullscreen:
            # after shell fg, cursor location changed; inline top unknown
            self.inline_top=None; self.app._inline_top=None
            self.query_inline_top()
        self.draw()

    def run(self):
        # wake pipe
        self.wake_r, self.wake_w = os.pipe()
        os.set_blocking(self.wake_r, False); os.set_blocking(self.wake_w, False)
        def on_winch(signum, frame):
            self.resize_pending=True
            try: os.write(self.wake_w, b'R')
            except Exception: pass
        def on_cont(signum, frame):
            self.resize_pending=True
            try: os.write(self.wake_w, b'C')
            except Exception: pass
        self._sigwinch_old=signal.signal(signal.SIGWINCH, on_winch)
        try: self._sigcont_old=signal.signal(signal.SIGCONT, on_cont)
        except Exception: pass
        # term restore on TERM/INT signals
        def on_term(signum, frame):
            try: self.term_restore()
            except Exception: pass
            signal.signal(signum, signal.SIG_DFL)
            os.kill(os.getpid(), signum)
        try: signal.signal(signal.SIGTERM, on_term)
        except Exception: pass
        # SIGINT as OS signal (ctrl-c byte is handled separately when raw)
        # Python KeyboardInterrupt is SIGINT python handler; install custom
        try: signal.signal(signal.SIGINT, on_term)
        except Exception: pass

        self.term_setup()
        self.query_inline_top()
        if self.inline_top is not None:
            self.app._inline_top=self.inline_top
        self.draw()
        app=self.app
        while not app.exit_requested:
            # wait for input or wake
            fds=[]
            if self.input_fd is not None and self.input_fd>=0:
                fds.append(self.input_fd)
            fds.append(self.wake_r)
            try:
                r,_,_=select.select(fds, [], [], None)
            except InterruptedError:
                continue
            except Exception:
                continue
            if self.wake_r in r:
                try: os.read(self.wake_r, 1024)
                except Exception: pass
                if self.resize_pending:
                    self.resize_pending=False
                    self.draw()
                continue
            if self.input_fd in r:
                try:
                    data=os.read(self.input_fd, 65536)
                except BlockingIOError:
                    continue
                except OSError:
                    data=b''
                if data==b'':
                    # EOF: original hangs waiting
                    # wait for signals forever
                    while not app.exit_requested:
                        try: signal.pause()
                        except Exception: break
                        if self.resize_pending:
                            self.resize_pending=False; self.draw()
                    break
                events=self.parser.feed(data)
                if not events:
                    continue
                need_draw=False
                for ev in events:
                    if app.exit_requested: break
                    if ev[0]=='ignore':
                        continue
                    if ev[0]=='suspend':
                        self.suspend(); need_draw=False; continue
                    if ev[0]=='char':
                        app.handle_event(('char', ev[1])); need_draw=True
                    elif ev[0]=='quit':
                        app.exit_requested=True; break
                    else:
                        # key/mouse etc
                        # adapt to App.handle_event expectations
                        if ev[0]=='mouse':
                            app.handle_event(ev); need_draw=True
                        else:
                            app.handle_event(ev); need_draw=True
                if need_draw and not app.exit_requested:
                    self.draw()
        self.term_restore()
        # restore signals
        try: signal.signal(signal.SIGWINCH, self._sigwinch_old)
        except Exception: pass
        return 0

