            if desired>maxoff: desired=maxoff
            app.scroll_offset=desired
        else:
            maxoff=max(0, total-vh)
            if app.scroll_offset>maxoff: app.scroll_offset=maxoff
        offset=app.scroll_offset
        viewport=lines[offset:offset+vh]
        # pad viewport to vh for fullscreen
        app._vp_offset=offset; app._vp_w=w; app._inline_top=self.inline_top
        app._vp_h=vh
        if self.fullscreen:
            out=bytearray()
            out.extend(b"\x1b[H")
            for i in range(vh):
                out.extend(("\x1b[%d;1H\x1b[2K"% (i+1)).encode())
                if i < len(viewport):
                    bts, width = self.line_to_bytes(viewport[i], w)
                    out.extend(bts)
                    if width < w:
                        out.extend(b' '*(w-width))
                # else blank cleared
            try: os.write(self.out_fd, bytes(out))
            except Exception: pass
            self.printed_height=vh
            self.first=False
        else:
            out=bytearray()
            if not self.first and self.printed_height>0:
                if self.printed_height>1:
                    out.extend(("\x1b[%dA"% (self.printed_height-1)).encode())
                out.extend(b"\r")
            for i, line in enumerate(viewport):
                out.extend(b"\x1b[2K\r")
                bts, width = self.line_to_bytes(line, w)
                out.extend(bts)
                if i != len(viewport)-1:
                    out.extend(b"\r\n")
            new_h=len(viewport)
            if not self.first and new_h < self.printed_height:
                extra=self.printed_height-new_h
                for _ in range(extra):
                    out.extend(b"\r\n\x1b[2K")
                if extra>0:
                    out.extend(("\x1b[%dA\r"%extra).encode())
            try: os.write(self.out_fd, bytes(out))
            except Exception: pass
            self.printed_height=new_h
            self.first=False

    def suspend(self):
        self.term_restore()
        # reset printed state after resume we will redraw fresh inline
        old_handler=signal.getsignal(signal.SIGTSTP)
        try:
            signal.signal(signal.SIGTSTP, signal.SIG_DFL)
            os.kill(os.getpid(), signal.SIGTSTP)
        finally:
            # after resume
            try: signal.signal(signal.SIGTSTP, old_handler)
            except Exception: pass
        self.term_setup()
        self.first=True; self.printed_height=0
        if not self.fullscreen:
            # after shell fg, cursor location changed; inline top unknown
            self.inline_top=None; self.app._inline_top=None
            self.query_inline_top()
