    def run(self):
        # wake pipe
        self.wake_r, self.wake_w = os.pipe()
        os.set_blocking(self.wake_r, False); os.set_blocking(self.wake_w, False)
        def on_winch(signum, frame):
            self.resize_pending=True
            try: os.write(self.wake_w, b'R')
            except Exception: pass
        def on_cont(signum, frame):
            self.resize_pending=True
            try: os.write(self.wake_w, b'C')
            except Exception: pass
        self._sigwinch_old=signal.signal(signal.SIGWINCH, on_winch)
        try: self._sigcont_old=signal.signal(signal.SIGCONT, on_cont)
        except Exception: pass
        # term restore on TERM/INT signals
        def on_term(signum, frame):
            try: self.term_restore()
            except Exception: pass
            signal.signal(signum, signal.SIG_DFL)
            os.kill(os.getpid(), signum)
        try: signal.signal(signal.SIGTERM, on_term)
        except Exception: pass
        # SIGINT as OS signal (ctrl-c byte is handled separately when raw)
        # Python KeyboardInterrupt is SIGINT python handler; install custom
        try: signal.signal(signal.SIGINT, on_term)
        except Exception: pass

        self.term_setup()
        self.query_inline_top()
        if self.inline_top is not None:
            self.app._inline_top=self.inline_top
        self.draw()
        app=self.app
        while not app.exit_requested:
            # wait for input or wake
            fds=[]
            if self.input_fd is not None and self.input_fd>=0:
                fds.append(self.input_fd)
            fds.append(self.wake_r)
            try:
                r,_,_=select.select(fds, [], [], None)
            except InterruptedError:
                continue
            except Exception:
                continue
            if self.wake_r in r:
                try: os.read(self.wake_r, 1024)
                except Exception: pass
                if self.resize_pending:
                    self.resize_pending=False
                    self.draw()
                continue
            if self.input_fd in r:
                try:
                    data=os.read(self.input_fd, 65536)
                except BlockingIOError:
                    continue
                except OSError:
                    data=b''
                if data==b'':
                    # EOF: original hangs waiting
                    # wait for signals forever
                    while not app.exit_requested:
                        try: signal.pause()
                        except Exception: break
                        if self.resize_pending:
                            self.resize_pending=False; self.draw()
                    break
                events=self.parser.feed(data)
                if not events:
                    continue
                need_draw=False
                for ev in events:
                    if app.exit_requested: break
                    if ev[0]=='ignore':
                        continue
                    if ev[0]=='suspend':
                        self.suspend(); need_draw=False; continue
                    if ev[0]=='char':
                        app.handle_event(('char', ev[1])); need_draw=True
                    elif ev[0]=='quit':
                        app.exit_requested=True; break
                    else:
                        # key/mouse etc
                        # adapt to App.handle_event expectations
                        if ev[0]=='mouse':
                            app.handle_event(ev); need_draw=True
                        else:
                            app.handle_event(ev); need_draw=True
                if need_draw and not app.exit_requested:
                    self.draw()
