        # restore signals
        try: signal.signal(signal.SIGWINCH, self._sigwinch_old)
        except Exception: pass
        return 0

# ================= CLI / main =================

def eprint_bytes(b):
    try: os.write(2, b)
    except Exception: pass

def main(argv):
    help_flag=False; version_flag=False; key_flag=False; fullscreen=False
    positional=[]
    i=1
    after_dd=False
    invalid=False
    while i < len(argv):
        arg=argv[i]
        if after_dd:
            positional.append(arg)
        elif arg=="--":
            after_dd=True
        elif arg.startswith("--"):
            name=arg[2:]
            if name=="help": help_flag=True
            elif name=="version": version_flag=True
            elif name in ("key","keybinding"): key_flag=True
            elif name=="fullscreen": fullscreen=True
            else: invalid=True
        elif arg.startswith("-") and arg!="-" and len(arg)>1:
            # short cluster
            for ch in arg[1:]:
                if ch=='h': help_flag=True
                elif ch=='v': version_flag=True
                elif ch=='k': key_flag=True
                elif ch=='f': fullscreen=True
                else: invalid=True
        else:
            positional.append(arg)
        i+=1
    if len(positional)>1:
        invalid=True
    if invalid:
        eprint_bytes(b"Invalid arguments\n")
        return 1
    if help_flag:
        os.write(1, HELP_TEXT.encode()); return 0
    if version_flag:
        os.write(1, (VERSION+"\n").encode()); return 0
    if key_flag:
        os.write(1, key_table_bytes()); return 0

    filename=positional[0] if positional else None
    if filename is not None:
        # file
        try:
            if os.path.isdir(filename):
                data=b''
            else:
                with open(os.fsencode(filename), 'rb') as f:
                    data=f.read()
        except IsADirectoryError:
            data=b''
        except OSError:
            eprint_bytes(("Could not open file %s\n" % filename).encode('utf-8','surrogateescape'))
            return 1
        input_fd=0
        try: input_fd=sys.stdin.fileno()
        except Exception: input_fd=0
    else:
        os.write(1, b"Reading from stdin...")
        try:
            data=sys.stdin.buffer.read()
            if data is None: data=b''
        except Exception:
            data=b''
        # open /dev/tty for interaction if possible
        input_fd=0
        try:
            tty_fd=os.open("/dev/tty", os.O_RDONLY)
            input_fd=tty_fd
        except Exception:
            try: input_fd=sys.stdin.fileno()
            except Exception: input_fd=0

    parser=Parser(data)
    try:
        value=parser.parse()
    except JsonError as e:
        eprint_bytes(b"\n"+e.message+b"\n")
        return 1
    root=build_node(value, 0, None, None)
    out_fd=1
    try: out_fd=sys.stdout.fileno()
    except Exception: out_fd=1
    app=App(root, fullscreen, out_fd, input_fd)
    app._inline_top=None
    ctl=Controller(app, out_fd, input_fd, fullscreen)
    return ctl.run()

if __name__=="__main__":
    try:
        sys.exit(main(sys.argv))
    except KeyboardInterrupt:
        sys.exit(0)
    except BrokenPipeError:
        sys.exit(1)
