    start(exe, arg, w=w,h=h)
    snaps=[]
    def get():
        plain=[l.rstrip() for l in cap().splitlines()]
        esc=cap(esc=True).splitlines()
        # For fullscreen, plain is whole pane; for inline results may include prompt lines etc - caller decides
        return (plain, esc)
    snaps.append(("initial", get()))
    for name, fn in actions:
        fn()
        snaps.append((name, get()))
    # quit if still running? send q
    try: lit("q")
    except: pass
    kill()
    return snaps

def act_key(k):
    return (k, lambda: send(k))
def act_lit(k):
    return (f"lit:{k}", lambda: lit(k))
def act_down(n=1):
    def f():
        for i in range(n): send("Down", delay=0.12)
    return (f"Downx{n}", f)

def compare(js, actions, w=80,h=24, mode="-f", label=""):
    print("=====",label,"js=",js if isinstance(js,str) else json.dumps(js)[:200])
    orig=run_one(EXE_ORIG, js, actions, w,h,mode)
    mine=run_one(EXE_MINE, js, actions, w,h,mode)
