    for (name1, snap1),(name2,snap2) in zip(orig,mine):
        if snap1!=snap2:
            ok=False
            print(f" MISMATCH step {name1}")
            print("  ORIG plain:", [l for l in snap1[0] if l.strip()])
            print("  MINE plain:", [l for l in snap2[0] if l.strip()])
            print("  ORIG esc:", [l for l in snap1[1] if l.strip()])
            print("  MINE esc:", [l for l in snap2[1] if l.strip()])
        else:
            print(f" OK step {name1}")
    return ok

