def act_lit(k): return (f"lit:{k}", lambda: fast_lit(k))
def run_one_fast(exe, js, actions, w=70,h=25):
    open('/tmp/t/cur.json','w').write(js)
    dh.start(exe, f"-f /tmp/t/cur.json", w=w,h=h)
    def get(): return ([l.rstrip() for l in dh.cap().splitlines()], dh.cap(esc=True).splitlines())
    snaps=[("init",get())]
    for name,fn in actions:
        fn(); snaps.append((name,get()))
    fast_lit("q"); dh.kill(); return snaps

def rand_table_json():
    # object root or array of objs, nested sometimes
    keys=["a","bb","ccc","name","age","x"]
    rows=[]
    for i in range(random.randint(2,5)):
        o={}
        for k in random.sample(keys, random.randint(0,4)):
            o[k]=random.choice([i, i*10, "val", "long value here", True, None, [1,2], {"n":i}])
        rows.append(o)
    choice=random.random()
    if choice<0.5: return json.dumps(rows)
    if choice<0.75: return json.dumps({"data":rows, "other":123})
    return json.dumps({"outer":{"items":rows}})

if __name__=="__main__":
    random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 10)
    fails=0
    for trial in range(10):
        js=rand_table_json()
        actions=[]
        # navigate to table: for root array, Right+Enter; for nested, sequence more random will include various keys - simply random actions from set
        actions=[act_key("Right"),act_key("Enter")]
        for _ in range(8):
            k=random.choice(["Down","Up","Right","Left","Enter","Down","Right","Up","PPage","NPage"])
            actions.append(act_key(k))
            if random.random()<0.3: actions.append(act_lit(random.choice(["+","-","j","k","h","l"])))
        print(f"Trial {trial} js={js} acts={[a[0] for a in actions]}")
        orig=run_one_fast(dh.EXE_ORIG, js, actions)
        mine=run_one_fast(dh.EXE_MINE, js, actions)
        ok=True
        for (n1,s1),(n2,s2) in zip(orig,mine):
            if s1!=s2:
                ok=False; fails+=1
                print(" mismatch",n1)
                print("  ORIG",[l for l in s1[0] if l.strip()])
                print("  MINE",[l for l in s2[0] if l.strip()])
                print("  ORIG esc",[l for l in s1[1] if l.strip()])
                print("  MINE esc",[l for l in s2[1] if l.strip()])
                break
        print(" OK" if ok else " FAIL")
    print("fails",fails)
